const buildCL = (n: number): BoardTask['checklist'] => (SEED_CL[n] ?? []).map(([text, done], i) => ({ id: `sc${n}_${i}`, text, done }));
const clProgress = (cl: BoardTask['checklist'], fallback: number) => (cl.length ? Math.round((cl.filter((c) => c.done).length / cl.length) * 100) : fallback);

const seedTasks = (): BoardTask[] => SEED.map((d) => {
  const checklist = buildCL(d[0]);
  return {
    id: 't' + d[0], num: d[0], title: d[1], detalle: d[8], priority: prioFromScore(d[3]), score: d[3], progress: clProgress(checklist, d[4]),
    impacto: d[5], esfuerzo: d[6], scoreRazon: d[7] || undefined, deadline: '', labels: d[2], checklist, enPrioridad: false, origen: 'ia' as const,
    historial: [{ id: 'seed' + d[0], ts: SEED_TS, actor: 'ia', text: 'Creó la tarjeta' } as Hist],
  };
});

const normHist = (h: unknown[]): Hist[] => (Array.isArray(h) ? h : []).map((e) => {
  const o = (e ?? {}) as Record<string, unknown>;
  return { ...o, id: typeof o.id === 'string' && o.id ? o.id : 'h' + (Number(o.ts) || 0) } as Hist;
});
const normTask = (t: BoardTask): BoardTask => {
  const s = typeof t.score === 'number' && t.score > 0 ? clampScore(t.score) : 50;
  const checklist = Array.isArray(t.checklist) ? t.checklist : [];
  return { ...t, score: s, priority: prioFromScore(s), labels: Array.isArray(t.labels) ? t.labels : [], checklist, historial: normHist(t.historial as unknown[]) };
};
const normLabel = (l: Label): Label => ({ ...l, score: typeof l.score === 'number' && l.score >= 1 ? Math.min(100, Math.round(l.score)) : 50, detalle: typeof l.detalle === 'string' ? l.detalle : '', historial: normHist((l.historial as unknown[]) || []) });

function loadTasks(): BoardTask[] {
  try { const v = localStorage.getItem(K9); if (v) return (JSON.parse(v) as BoardTask[]).map(normTask); } catch { /* seed */ }
  return seedTasks();
}
function loadLabels(): Label[] {
  try { const p = localStorage.getItem(K_PROJS); if (p) return (JSON.parse(p) as Label[]).map(normLabel); } catch { /* default */ }
  return PROJS_DEFAULT;
}

// Agregar ideas nuevas SIN pisar tus ediciones: bumpeo MERGE_VERSION y en el próximo
// load se AGREGA al localStorage solo lo que falte (por id/num). No resetea.
const MERGE_VERSION = 'v1';
function mergeExtras(tasks: BoardTask[], labels: Label[]): { tasks: BoardTask[]; labels: Label[] } {
  try {
    if (localStorage.getItem('mako_plan_merge9') === MERGE_VERSION) return { tasks, labels };
    localStorage.setItem('mako_plan_merge9', MERGE_VERSION);
    const haveL = new Set(labels.map((l) => l.id));
    const haveT = new Set(tasks.map((t) => t.num));
    return {
      tasks: [...tasks, ...seedTasks().filter((t) => !haveT.has(t.num))],
      labels: [...labels, ...PROJS_DEFAULT.filter((p) => !haveL.has(p.id))],
    };
  } catch { return { tasks, labels }; }
}

// Reconciliar UNA vez el checklist de tareas puntuales al SEED corregido (marcar lo
// que ya se hizo). A diferencia de mergeExtras (que solo AGREGA tareas nuevas), esto
// pisa el checklist —y por ende el avance, que se deriva de él— SOLO de estas tareas,
// dejando intacto el resto del board, y DEJA RASTRO en el historial (actor 'ia' = MaKo)
// de cada ítem que MaKo completó en la tanda autónoma. Bump de versión para re-correrlo.
const RECONCILE_VERSION = 'v2';
const RECONCILE_TS = Date.parse('2026-07-13T21:00:00-06:00'); // cuándo MaKo lo hizo (TJ)
// Por tarea: los ítems que MaKo COMPLETÓ en esta tanda (los que pasaron a hecho ahora;
// no incluye los que ya estaban tildados). Alimenta el historial + son la allowlist.
const RECONCILE_DONE: Record<number, string[]> = {
  10: ['El webhook de Chatwoot busca el lead acotado al cliente', 'Tracking del VSL y la landing sin conexión cruda', 'La columna de cliente en las vistas de datos (mig 0084)', 'Auditoría de las 131 rutas + gates de rol que faltaban'],
  12: ['Tests de que cada consulta queda acotada al cliente (contrato TENANT_TABLES)', 'Más tests: scoring del guardián, fechas, Calendly, anti-inyección, journey'],
  34: ['Inyectarle a MaKo el funnel real (contexto + tool para consultarlo)'],
  65: ['Sumar los de Experimentos/Retro a la pantalla editable', "Corregir los carteles mal (Retro + 'núcleo no editable' en Contexto)"],
  89: ['Borrar el administrador de ángulos viejo', 'Borrar el navegador de anuncios huérfano', 'Borrar el retro viejo + 3 componentes huérfanos más'],
  92: ['Tab Graphics del board (matriz impacto×esfuerzo, pirámide, avance, salud)'],
  95: ['Migrar los desplegables nativos que quedaban', 'Los textos R1/R2 visibles ya están todos migrados'],
};
function reconcileChecklists(tasks: BoardTask[]): BoardTask[] {
  try {
    if (localStorage.getItem('mako_plan_reconcile') === RECONCILE_VERSION) return tasks;
    localStorage.setItem('mako_plan_reconcile', RECONCILE_VERSION);
    return tasks.map((t) => {
      const hechos = RECONCILE_DONE[t.num];
      const cl = buildCL(t.num);
      if (!hechos || !cl.length) return t;
      const entries: Hist[] = hechos.map((text, i) => ({ id: 'rec' + t.num + '_' + i, ts: RECONCILE_TS - i * 1000, actor: 'ia', text: `Completó "${text}"`, kind: 'task' }));
      return { ...t, checklist: cl, progress: clProgress(cl, t.progress), historial: [...entries, ...t.historial].slice(0, HIST_CAP) };
    });
  } catch { return tasks; }
}

export function PlanBoard({ user }: { user: BoardUser }) {
  const repo: Repo = {
    labelMode: 'multi', labelSingular: 'Proyecto', labelPlural: 'Proyectos',
    dismissableGauntlet: true, fathomExtract: true,
    createTask: async (d) => d, saveTask: async () => {}, deleteTask: async () => {},
    createLabel: async (l) => l, saveLabel: async () => {}, deleteLabel: async () => {},
  };
  const board = useBoard([], [], user, repo);
  const [hydrated, setHydrated] = useState(false);

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { const { tasks, labels } = mergeExtras(loadTasks(), loadLabels()); board.reset(reconcileChecklists(tasks), labels); setHydrated(true); }, []);
  useEffect(() => { if (hydrated) try { localStorage.setItem(K9, JSON.stringify(board.tasks)); } catch { /* no-op */ } }, [board.tasks, hydrated]);
  useEffect(() => { if (hydrated) try { localStorage.setItem(K_PROJS, JSON.stringify(board.labels)); } catch { /* no-op */ } }, [board.labels, hydrated]);

  if (!hydrated) return <main style={{ flex: 1 }} />;
  return <BoardShell board={board} />;
}
